/* Table de traductions — francais.
 *
 * Extraite de translations.js le 2026-09-19. Ce fichier ne contient QUE des donnees : la logique de
 * chargement, la liste des langues et la langue par defaut restent dans translations.js.
 *
 * POURQUOI TROIS FICHIERS. Reunies dans un seul module, les trois langues formaient un morceau de
 * 1,1 Mo que Vite ne pouvait pas decouper — et que LanguageContext charge au premier rendu. Chaque
 * visiteur telechargeait donc les trois langues pour en lire une : 374 Ko sur les 638 Ko du chemin
 * critique, soit 59 % du transfert, et 55 % du JavaScript a analyser. Separees, le francais part
 * avec l'application et les deux autres ne sont chargees qu'a la demande.
 *
 * Le contenu a ete DEPLACE tel quel, indentation d'origine comprise. Ne pas reindenter pour
 * « faire propre » : ces chaines portent des apostrophes echappees et des accolades de variables.
 *
 * Toute cle ajoutee ici doit l'etre dans les deux autres fichiers — scripts/check-i18n.mjs echoue
 * sinon, et c'est exactement son role. */
