      beforeOneOrder: 'Tu livres aussi pour une autre plateforme : une seule course Fairide à la fois, le temps de la terminer. (Modifiable dans « Autres plateformes » ; les livreurs qui ne travaillent que pour Fairide peuvent en tenir jusqu\'à trois.)',
      beforePayment: "Paiement : {base} de base par course jusqu'à {km} km, puis {perKm} par kilomètre entamé au-delà, à vélo comme en scooter ou en voiture, TVA comprise si tu y es assujetti. La distance est celle entre le commerce et l'adresse de livraison de la commande. Sur ce tarif, Fairide retient 10 % de frais de système (connexion, système, assurance des livreurs) : tu touches 90 %, et les pourboires en entier. Le prix t'est affiché avant d'accepter, et tes gains sont versés chaque lundi sur ton compte via Stripe, automatiquement, pour les courses de la semaine écoulée.",
