      photoValidate: 'Valider ce commerce',
      photoSaved: 'Commerce ajouté avec sa photo.',
      guideTitle: 'Démarchage : comment on s\'y prend',
      guideIntro: 'Le flyer, le pitch, les techniques qui marchent, et la posture Fairide.',
      guideShow: 'Voir le guide',
      guideHide: 'Masquer le guide',
      guideRepTitle: 'Tu représentes Fairide',
      guideRepText: 'Souriant, poli, ponctuel, honnête : chaque commerçant se souvient de toi avant de se souvenir de l\'app. On ne force jamais, on ne dénigre jamais les autres plateformes, on ne promet rien qui n\'est pas sur le flyer. Une réponse floue ? On dit « je vérifie et je reviens vers vous », et on le fait.',
      guideBeforeTitle: 'Avant de partir',
      guideBefore1: 'Une pile de flyers, un stylo, ton téléphone chargé avec l\'app Fairide ouverte (pour montrer une fiche et une carte en ligne).',
      guideBefore2: 'Choisis ta zone dans « Zones » et prends-la : les autres ne passeront pas derrière toi.',
      guideBefore3: 'Le bon moment : entre 14 h 30 et 17 h 30, ou le matin avant 11 h 30. Jamais pendant le rush.',
      guideBefore4: 'Demande le patron ou le gérant. S\'il n\'est pas là, note son prénom et l\'heure où il est là, et reviens.',
      guidePitchTitle: 'Le pitch en 30 secondes',
      guidePitchText: '« Bonjour, je suis [prénom], de Fairide, la nouvelle app bruxelloise de livraison et de vente à emporter. Une seule règle : 20 € par mois, et 10 % uniquement sur la livraison et le paiement en ligne. Ce que le client paie chez vous, c\'est 100 % pour vous. Sur une commande de 40 € livrée, vous gardez 36 € au lieu de 28 €. Ça vous intéresse que je vous montre en deux minutes ? »',
      guidePitch1: 'Une phrase, un chiffre, une question. Puis tu te tais et tu écoutes.',
      guidePitch2: 'Montre le flyer : la comparaison 28 € / 36 € parle toute seule.',
      guidePitch3: 'Premier mois offert : il essaie l\'à emporter et la livraison sans rien payer pendant un mois, et ce qui est payé sur place reste à 100 % pour lui. Et si ses commandes ne dépassent pas 50 € sur un mois, il ne paie pas l\'abonnement de ce mois : offert ou remboursé.',
      guidePitch4: 'Terminal offert aux premiers restaurants inscrits, caution pour les suivants : c\'est l\'argument pour signer maintenant.',
      guideTechTitle: 'Les techniques qui marchent',
      guideTech1: 'Pose des questions avant de vendre : « Vous êtes sur Uber Eats ? Ça vous coûte combien par mois ? » Le commerçant se convainc lui-même.',
      guideTech2: 'Parle de son argent, pas de nos fonctionnalités : + 8 € par commande, 800 € par mois pour 100 commandes.',
      guideTech3: 'Inscris-le sur place, avec lui, en 5 minutes : compte créé = ta prime de 20 € acquise. Relie ensuite ta fiche au commerce dans Sales.',
      guideTech4: 'Sa carte ? Il n\'a rien à faire : Fairide la crée à partir de son site, d\'Uber Eats ou d\'une photo de sa carte. Dis-le clairement.',
      guideTech5: 'Note tout dans Sales dès que tu sors : étape, ce qu\'il a dit, sa prochaine dispo. Une visite non notée est une visite perdue.',
      guideTech6: 'Un « oui » non signé n\'existe pas : fixe un rendez-vous précis (« jeudi 15 h, je repasse avec le terminal ? »).',
      guideNoTitle: 'Si c\'est non, c\'est pas grave',
      guideNo1: 'On reste pro et souriant : « Pas de souci, merci pour votre temps. »',
      guideNo2: 'On laisse le flyer sur le comptoir : « Je vous le laisse, tout est dessus, avec notre numéro. »',
      guideNo3: 'On lui souhaite une agréable journée, et on sort.',
      guideNo4: 'Dans Sales : étape « Plus tard », une note sur la raison du non, et une prochaine action la semaine d\'après.',
      guideNo5: 'On repasse la semaine suivante, sans insister : « Je passais dans le coin, vous avez eu le temps d\'y penser ? » Beaucoup de « non » deviennent « oui » à la deuxième visite.',
      guideYesTitle: 'Si c\'est oui',
      guideYes1: 'Crée le compte avec lui sur place (fairide.be › Inscription › Restaurant) : e-mail, téléphone, adresse.',
      guideYes2: "Explique le calendrier : à emporter le 1er novembre, livraison dès que les livreurs sont assez nombreux (annoncée par e-mail).",
      guideYes3: 'Dis-lui ce qui se passe ensuite : Fairide crée sa carte, il la vérifie, l\'équipe le valide, puis le terminal est installé avec lui en 30 minutes.',
      guideYes4: 'Relie ta fiche au commerce dans Sales et passe-la à « Inscrit sur Fairide » : ta prime est comptée.',
