      sponsors_desc: 'Les emplacements du site réservés au logo d\'un partenaire, et le fichier chargé pour chacun.',
      sponsors_help: 'Un petit logo partenaire par rangée de la liste des commerces, à côté du titre. Personne ne le voit à part l\'équipe tant que « Visible du public » n\'est pas coché pour la rangée.',
