      crm: 'CRM',
      crm_desc: 'Pipeline commercial : prospects, relances, conversion en restaurant partenaire.',
      crm_help: 'Glisse un prospect d\'une colonne à l\'autre pour changer son étape. Une relance en retard s\'affiche en rouge. « Actif » convertit le prospect en restaurant.',
