      promotions_desc: 'Codes promo : solde offert aux clients, mois d\'essai pour les restaurateurs, suivi des usages.',
      promotions_help: 'Un code désactivé ne peut plus être utilisé mais garde son historique. Limite le nombre d\'utilisations pour une campagne ponctuelle.',
      finance: 'Finance',
