      payments_help: 'Chaque commande payée apparaît ici avec son paiement Stripe ; les payouts suivent les virements vers les comptes connectés. Le rapprochement signale les écarts.',
      invoices: 'Facturation',
      invoices_desc: 'Factures de commission, relevés de paiement et relevés des ventes des livreurs, notes de crédit.',
      invoices_help: 'Les factures du mois précédent sont générées automatiquement ; tu peux les envoyer par e-mail, les marquer payées ou émettre une note de crédit. PDF et UBL téléchargeables.',
      accounting: 'Comptabilité',
