      step1: "Inscris-toi à la Banque-Carrefour des Entreprises par un guichet d'entreprises agréé (activité : livraison à vélo ou en véhicule). Tu reçois ton numéro, à indiquer dans ton dossier Fairide.",
      step2Title: "2. Ta caisse d'assurances sociales",
      step2: "Affilie-toi à une caisse d'assurances sociales avant de commencer. Étudiant de 18 à 25 ans inscrit pour au moins 27 crédits ? Demande le statut d'étudiant-indépendant : aucune cotisation sous {exemption} de revenu net cette année. Sinon, indépendant à titre principal ou complémentaire.",
      step3Title: "3. La TVA",
