      printerCompatTitle: 'Quelle imprimante ?',
      printerCompat1: 'Imprimante thermique ESC/POS en Bluetooth Low Energy (BLE), papier 58 ou 80 mm : par exemple Xprinter, Munbyn, Goojprt, Netum, Phomemo (modèles « BLE »). Un modèle en Bluetooth classique (SPP) n\'est pas visible depuis un navigateur.',
      printerCompat2: 'Depuis l\'application Fairide sur Android (tablette ou téléphone), sur PC Windows, Mac ou Chromebook : Bluetooth direct vers l\'imprimante. Sur iPad et iPhone, l\'application n\'a pas accès au Bluetooth : utilise « Imprimer le bon de livraison », qui passe par AirPrint ou une imprimante Wi-Fi.',
      printerCompat3: 'Imprimante USB, Wi-Fi ou réseau (Epson, Star…) : installe-la sur l\'appareil comme n\'importe quelle imprimante, puis « Imprimer le bon de livraison » l\'utilise via la boîte d\'impression de l\'appareil. Sur Android, l\'appli gratuite RawBT permet aussi d\'y envoyer le ticket.',
