      appStepsTitle: 'Imprimer depuis l\'application, sur cet appareil',
      appInstalled: 'Tu es dans l\'application Fairide installée : l\'impression fonctionne comme décrit ci-dessous.',
      appInstallHint_android: 'Conseil : installe l\'application pour le service. Dans Chrome, menu ⋮ → « Installer l\'application » (ou « Ajouter à l\'écran d\'accueil »). Elle s\'ouvre ensuite plein écran, comme une appli.',
      appInstallHint_ios: 'Conseil : installe l\'application pour le service. Dans Safari, bouton Partager → « Sur l\'écran d\'accueil ». Elle s\'ouvre ensuite plein écran, comme une appli.',
      appInstallHint_desktop: 'Conseil : installe l\'application pour le service. Dans Chrome ou Edge, icône « Installer » à droite de la barre d\'adresse (ou menu → « Installer Fairide »). Elle s\'ouvre ensuite dans sa propre fenêtre.',
      appSteps_android_1: 'Allume l\'imprimante thermique Bluetooth (BLE) et active le Bluetooth de la tablette ou du téléphone.',
      appSteps_android_2: 'Touche « Connecter mon imprimante », choisis-la dans la liste, puis imprime un ticket de test. Coche « Impression automatique » pour que chaque nouvelle commande sorte toute seule.',
      appSteps_android_3: 'Pendant le service, garde l\'application ouverte sur Commandes. Si tu la fermes, reconnecte l\'imprimante en un clic. Sans imprimante thermique : « Imprimer le bon de livraison » envoie le ticket vers n\'importe quelle imprimante Wi-Fi installée sur l\'appareil (ou via l\'appli RawBT).',
      appSteps_ios_1: "Sur iPhone et iPad, l'application web n'a pas accès au Bluetooth (limite d'Apple). Deux solutions :",
      appSteps_ios_2: 'Ouvre une commande et touche « Imprimer le bon de livraison » : la boîte d\'impression d\'Apple propose toute imprimante AirPrint ou Wi-Fi du réseau (Epson, Star, Brother…). Choisis-la une fois, elle reste proposée.',
      appSteps_ios_3: 'Pour une vraie imprimante à tickets thermique au comptoir, garde une tablette Android (même d\'entrée de gamme) connectée en Bluetooth : elle imprime automatiquement chaque commande, pendant que tu gères le reste sur iPhone.',
