      allergyHow: "Ta commande n'est préparée qu'une fois que le commerce a confirmé pouvoir respecter ta demande. S'il ne le peut pas, il la refuse et tu es intégralement remboursé.",
      allergyCallFirst: 'Allergie sévère : appelle le commerce avant de commander, au {phone}.',
      ageDeclaration: 'J\'ai {age} ans ou plus. Une pièce d\'identité me sera demandée à la remise ; sans preuve, les produits alcoolisés ne me seront pas remis.',
      termsAcceptPrefix: 'J\'accepte les',
      termsLink: 'conditions générales',
      feesHowTitle: 'Comment les frais sont calculés',
      feesHowBody: 'En livraison s\'ajoutent des frais de livraison, calculés selon la distance (5 € pour le premier kilomètre, puis 0,80 € par kilomètre entamé, TVA éventuelle comprise). Ils comprennent les frais de système de Fairide. Quand les livreurs disponibles demandent un tarif minimum plus élevé, ces frais peuvent être relevés, de 3 € au plus. Rien d\'autre ne s\'ajoute : le montant exact s\'affiche avant le paiement. À emporter : pas de frais.',
