      vat: 'TVA',
      sellerTitle: 'Vendeur',
      sellerProfessional: 'vendeur professionnel.',
      sellerContract: "La vente est conclue entre toi et ce commerce ; Fairide assure la mise en relation, le paiement et, le cas échéant, la livraison.",
      allergensTitle: 'Allergènes',
      allergensAskBefore: "le commerce te renseigne avant ta commande au",
      reportRestaurant: 'Signaler ce commerce',
      rankingLink: 'Comment nous classons les commerces',
      dsaContactTitle: 'Point de contact (règlement sur les services numériques)',
      dsaContactBody: 'Point de contact unique pour les autorités et pour les utilisateurs (DSA, art. 11 et 12) : dsa@fairide.be. Langues acceptées : français, néerlandais, anglais. Pour signaler un produit, un contenu ou un commerce, utilisez aussi le lien « Signaler » de la fiche du commerce.',
      rankingPageTitle: 'Classement des commerces · Fairide',
      rankingPageDescription: 'Comment Fairide ordonne les commerces.',
      rankingTitle: 'Comment nous classons les commerces',
      ranking_orderTitle: 'L\'ordre par défaut (« Recommandé »)',
      ranking_order: "Quand vous cherchez un mot ou choisissez un filtre, la page des commerces montre une seule liste, sans aucune position payée. Les commerces de votre commune viennent d'abord, puis ceux des communes voisines, de proche en proche. Votre commune est celle de l'adresse de votre compte (sa ville, ou à défaut son code postal), sinon celle de l'adresse tapée sur la page d'accueil. Dans une même commune, les vrais commerces passent avant d'éventuelles fiches de démonstration, puis le commerce inscrit le plus récemment passe devant. Sans commune connue, ou quand vous filtrez sur une commune, seul ce dernier ordre s'applique. La page Recherche et la carte suivent aussi cet ordre d'inscription, sans tenir compte de votre commune.",
      ranking_sortsTitle: 'Les filtres',
      ranking_sorts: "Il n'y a pas d'autre tri pour le moment. Les filtres (type de cuisine, commune, mot cherché) retirent des commerces de la liste : ils ne la réordonnent pas.",
      ranking_rowsTitle: 'Les rangées de la page d\'accueil',
      ranking_rows: "Sans recherche ni filtre, la page montre des rangées, dans cet ordre.\n**À la une près de toi** : jusqu'à cinq commerces qui ont leur propre photo (pas les commerces « Carte seule »), ceux qui sont ouverts avant ceux qui sont fermés, puis les plus proches de chez vous. Aucune position n'y est payée.\n**Déjà sur Fairide** : jusqu'à huit vrais commerces inscrits dont la carte est complète. L'équipe Fairide peut donner à la main un rang à certains d'entre eux : ils passent alors en tête, dans l'ordre de ce rang. Les autres sont classés par un score : 100 points si le commerce est déjà ouvert aux clients, 30 s'il a sa propre photo et 20 si sa carte est complète ; à score égal, le plus récent d'abord. Aucune position n'y est payée.\n**Autour de toi** : les 15 commerces les plus proches de l'adresse de votre compte, à vol d'oiseau, toutes communes confondues (sans les supermarchés). Si votre adresse n'a pas de position connue : votre commune, puis les communes voisines. S'il y en a moins de six, la rangée est complétée par d'autres commerces, dans l'ordre par défaut.\n**Tes envies** (application seulement) : si vous avez choisi des envies à l'accueil (pizza, burgers…), les commerces qui y répondent, dans le même ordre qu'« Autour de toi », 15 au plus ; ces choix restent dans votre téléphone. Aucune position n'y est payée.\n**Livraison offerte** et **Livraison dès 3 €** : seulement quand la livraison est ouverte et possible chez vous maintenant (adresse dans la zone du commerce, livreur libre). La première montre les commerces qui offrent la livraison, ou l'offrent dès un montant ; la seconde, ceux dont la livraison coûte 3 € au plus.\n**Offres** : les commerces qui proposent une promotion qu'ils ont eux-mêmes créée.\n**Rangées par type de cuisine** (« Pizza »…), ouvertes par Fairide : les commerces de ce type, principal ou secondaire.\n**Healthy** : les commerces qui ont au moins un plat qu'ils ont marqué ainsi.\n**Supermarchés** : supermarchés, night shops, boulangeries et boucheries.\n**À découvrir** : jusqu'à huit commerces où vous n'avez pas encore commandé, à moins de 10 km de votre adresse quand elle a une position connue.\nDans ces rangées (sauf les quatre premières), l'ordre est le suivant : votre commune d'abord, puis les communes voisines ; dans une même commune, un ordre tiré au hasard pour votre visite. Une exception : quand un commerce a payé une position dans la rangée pour votre commune (voir ci-dessous), les autres gardent l'ordre propre à la rangée : le plus de plats marqués d'abord pour Healthy ; la livraison la moins chère d'abord pour les deux rangées de livraison ; l'ordre de la liste décrit plus haut pour les autres (toujours au hasard pour À découvrir). Seule « Autour de toi » est complétée : les autres rangées ne montrent que les commerces qui y répondent.",
      ranking_notPaidTitle: 'Les positions payées (« Sponsorisé »)',
      ranking_notPaid: "Un commerce peut payer pour être placé à l'une des premières positions d'une rangée de la page des commerces (de la 1re à la 10e au plus, selon ce que Fairide met en vente), pour une durée limitée. Sa carte porte alors la mention « Sponsorisé ». Les limites : la position ne vaut que dans la commune du commerce, et seulement pour les clients de cette commune (celle de leur compte ou de l'adresse tapée sur l'accueil) ; sans commune connue, rien n'est placé ainsi. Une position n'est tenue que par un commerce à la fois, et un commerce ne tient qu'une position par rangée. Fairide valide chaque demande, ou l'accepte automatiquement (premier arrivé, premier servi) quand l'équipe a choisi ce mode. Il n'y a aucune position payée dans « À la une près de toi », « Déjà sur Fairide », « Tes envies », la liste filtrée, la page Recherche ni la carte. Le commerce doit appartenir à la rangée : payer ne fait pas entrer un commerce sans plat vegan dans « Vegan ». Deux précisions : dans « Autour de toi », le commerce payant (toujours de votre commune) peut apparaître même s'il n'est pas parmi les 15 plus proches ; dans « À découvrir », même s'il n'est pas sorti au tirage, s'il est à plus de 10 km ou si vous y avez déjà commandé. En dehors de ces positions signalées, aucun commerce ne paie pour être mieux placé : la commission (10 % au plus) et l'abonnement sont les mêmes pour tous et n'influencent pas l'ordre d'affichage.",
      ranking_contestTitle: 'Contester',
      ranking_contest: 'Pour contester la place de votre commerce : contact@fairide.be. Pour signaler un contenu illicite : le lien « Signaler » de la fiche, ou dsa@fairide.be.',
